/* Types */
/**  What approving a fact wrote. */
export type ApprovalOutcomeDto = {
	/**  The fact that was approved. */
	fact_id: string,
	/**
	 *  Ids newly asserted into the overlay graph. More than one when
	 *  approving an object also released morphisms it was the missing
	 *  endpoint of; empty when the fact is an edge still waiting on an
	 *  endpoint.
	 */
	promoted: string[],
};

/**  Where one source arrow goes. */
export type ArrowMoveDto = {
	/**  The source arrow. */
	from: string,
	/**  The destination path, rendered (`Item.label`). */
	to_path: string,
	/**  The destination path's arrows, in application order. */
	to_arrows: string[],
	/**  Other source arrows landing on the same path. */
	shared_with: string[],
};

/**  The recorded contribution of each ranking boost to a hit's score. */
export type BoostsDto = {
	/**  Title match (query terms in the heading breadcrumb's head). */
	title: number | null,
	/**  Path match (query terms in the stored path). */
	path: number | null,
	/**  Recency (modification-time decay). */
	recency: number | null,
	/**  Graph proximity to a `linked-to:` document. */
	graph: number | null,
};

export type CloudConnectionState = "disconnected" | "connected" | "reauthorize";

export type CloudDocumentQueryResponse = {
	query_id: string,
	provider: CloudProvider,
	schema_version: string,
	scanned: number,
	rows: CloudDocumentRow[],
};

export type CloudDocumentRow = {
	source_id: string,
	record_key: string,
	fields: unknown,
};

export type CloudFilterInput = {
	field: string,
	operator: CloudFilterOperator,
	value: string,
};

export type CloudFilterOperator = "eq" | "lt" | "le" | "gt" | "ge" | "glob";

export type CloudProvider = "google-drive" | "dropbox";

export type CloudSourceDto = {
	id: string,
	provider: CloudProvider,
	label: string,
	connection: CloudConnectionState,
	enabled: boolean,
};

export type CloudSourceError = { kind: "invalid-configuration" } | { kind: "source-not-found" } | { kind: "credential-unavailable" } | { kind: "credential-missing" } | { kind: "corrupt-registry" } | { kind: "unsupported-version"; found: number; expected: number } | { kind: "persist-failed" } | { kind: "rollback-failed" } | { kind: "client-configuration-missing" } | { kind: "oauth-callback-unavailable" } | { kind: "oauth-invalid-callback" } | { kind: "oauth-state-mismatch" } | { kind: "oauth-denied" } | { kind: "oauth-timeout" } | { kind: "oauth-transport" } | { kind: "provider-rejected" } | { kind: "source-paused" } | { kind: "query-invalid"; detail: string } | { kind: "query-failed"; detail: string };

export type CloudSourcesSnapshot = {
	version: number,
	sources: CloudSourceDto[],
};

/**  Why a chain did not produce a validated composite. */
export type CompositionFailureDto = {
	/**  `"structure"`, `"leg"`, or `"composite"`. */
	kind: string,
	/**  Which leg, for a `"leg"` failure. */
	leg: number | null,
	/**  The kernel's own message. */
	message: string,
	/**  The individual validation errors, for a `"leg"` or `"composite"` failure. */
	errors: string[],
};

/**  One leg of a composed chain. */
export type CompositionLegDto = {
	/**  The leg's registered mapping name. */
	name: string,
	/**  Source schema name. */
	src: string,
	/**  Destination schema name. */
	dst: string,
	/**  The persisted version ordinal of the mapping, when it has one. */
	version: number | null,
	/**  `blake3:` checksum of the persisted mapping, when it has one. */
	checksum: string | null,
};

/**  What becomes of one concept of the old version. */
export type ConceptClassificationDto = {
	/**  The old version's concept. */
	concept: ConceptDto,
	/**  `"mapped_exactly"`, `"needs_classification"`, or `"unmappable"`. */
	verdict: string,
	/**  The change that makes it ambiguous, for `"needs_classification"`. */
	reason: string | null,
};

/**  One named piece of a schema. */
export type ConceptDto = {
	/**  `"entity"`, `"arrow"`, or `"attribute"`. */
	kind: string,
	/**  The concept's name, as the schema declares it. */
	name: string,
};

/**  The result of running every registered schema's laws over the graph. */
export type ConstraintReport = {
	/**  How many schemas were checked. */
	schemas_checked: number,
	/**  Every violation found, unmodified. */
	violations: ViolationDto[],
};

export type DiagnosticError = { kind: "confirmation-required" } | { kind: "corrupt-settings"; reason: DiagnosticFailureReason } | { kind: "invalid-event"; reason: DiagnosticFailureReason } | { kind: "write-failed"; reason: DiagnosticFailureReason } | { kind: "export-failed"; reason: DiagnosticFailureReason } | { kind: "clear-failed"; reason: DiagnosticFailureReason } | { kind: "reveal-failed"; reason: DiagnosticFailureReason };

export type DiagnosticErrorCode = "invalid-source" | "source-missing" | "source-unreadable" | "watcher-unavailable" | "index-unavailable" | "persistence-unavailable";

export type DiagnosticEvent = { kind: "application-started" } | { kind: "workspace"; source_id: string; active: boolean } | { kind: "watcher"; source_id: string; state: DiagnosticWatcherState; error: DiagnosticErrorCode | null } | { kind: "index"; source_id: string; phase: DiagnosticIndexPhase; files_done: number; files_total: number; chunks: number; error: DiagnosticErrorCode | null } | { kind: "error"; code: DiagnosticErrorCode };

export type DiagnosticExport = {
	status: DiagnosticExportStatus,
	bytes_written: number,
};

export type DiagnosticExportStatus = "cancelled" | "exported";

export type DiagnosticFailureReason = "authority-unavailable" | "authority-changed" | "lock-unavailable" | "settings-unavailable" | "settings-invalid" | "event-invalid" | "storage-unavailable" | "destination-unavailable";

export type DiagnosticIndexPhase = "loading" | "importing" | "reembedding" | "done" | "model-unavailable" | "error";

export type DiagnosticInfo = {
	level: DiagnosticLevel,
	max_file_bytes: number,
	max_retained_files: number,
	max_export_bytes: number,
};

export type DiagnosticLevel = "errors" | "standard" | "verbose";

export type DiagnosticWatcherState = "idle" | "watching" | "error";

/**  The bytes of a document plus the provenance a conflict guard needs. */
export type DocPayload = {
	/**  UTF-8 file contents (lossily decoded; invalid bytes become U+FFFD). */
	content: string,
	/**  Modification time in milliseconds since the Unix epoch. */
	mtime: number | null,
	/**
	 *  blake3 hex digest of the raw file bytes — the anchor for the later
	 *  external-edit conflict guard (P3).
	 */
	hash: string,
};

/**  Where one source entity's rows go. */
export type EntityMoveDto = {
	/**  The source entity. */
	from: string,
	/**  The destination entity. */
	to: string,
	/**  Other source entities landing there. */
	shared_with: string[],
};

/**  How many stored objects of one source entity move without a decision. */
export type EntityObjectCountDto = {
	/**  The source entity. */
	entity: string,
	/**  The qualified name the corpus stores its objects under. */
	qualified: string,
	/**  How many are stored. */
	objects: number,
	/**  How many move mechanically. */
	auto_mapped: number,
	/**  How many need a human decision. */
	needs_decision: number,
	/**  Why, when they do. */
	reason: string | null,
};

/**  The full per-hit score breakdown (see [`SearchQuery::explain`]). */
export type ExplainDto = {
	/**  1-based lexical rank, when the chunk appeared in the FTS results. */
	lex_rank: number | null,
	/**  1-based semantic rank, when the chunk appeared in the vector results. */
	sem_rank: number | null,
	/**  The fused reciprocal-rank score before boosts. */
	rrf_score: number | null,
	/**  Each boost's recorded contribution. */
	boosts: BoostsDto,
	/**  `rrf_score + boosts.total()` — the ordering key. */
	final_score: number | null,
	/**  The index version the semantic modality searched, if it ran. */
	index_version: string | null,
	/**  That version's embedding model. */
	embedding_model: string | null,
	/**  The provenance chain. */
	provenance: ProvenanceDto,
};

/**  A fact's derivation record — every field the extractor stamped, unmodified. */
export type FactProvenanceDto = {
	/**  Repo-relative source file. */
	file: string | null,
	/**  First cited line (1-based, inclusive). */
	start_line: number | null,
	/**  Last cited line (1-based, inclusive). */
	end_line: number | null,
	/**  blake3 of exactly the lines the range names. */
	content_hash: string | null,
	/**  Version of the schema the fact is typed against. */
	schema_version: string | null,
	/**  Extractor id and version (e.g. `mdreader.decision@1`). */
	extractor: string | null,
	/**  Extractor confidence in `[0, 1]`. */
	confidence: number | null,
	/**  The reviewer stamped at approval time; `None` until a human accepts it. */
	approved_by: string | null,
};

/**  The one assembled semantic `Document`. */
export type FederatedDocumentDto = {
	/**  Workspace-relative natural key. */
	path: string,
	/**  All six schema fields in stable name order. */
	fields: FederatedFieldDto[],
};

/**  The shipping response shown by MDReader's Semantic Inspector. */
export type FederatedDocumentResponse = {
	/**  Stable identity of this execution. */
	query_id: string,
	/**  Persisted schema version/checksum when the engine has catalogued it. */
	schema: FederatedSchemaDto,
	/**  `complete` or `partial`; derived from the source reports. */
	completeness: string,
	/**  The exact requested document. */
	document: FederatedDocumentDto,
	/**  One report for filesystem, Git, and frontmatter, in execution order. */
	sources: FederatedSourceDto[],
};

/**  One semantic field and its complete source attribution. */
export type FederatedFieldDto = {
	/**  Semantic field name. */
	name: string,
	/**  Selected JSON value, or `None` when every provider was absent. */
	value: unknown | null,
	/**  Winning source, or `None` when the field is absent. */
	winner: string | null,
	/**  Every declared provider, including losers and absences. */
	providers: FederatedProviderDto[],
	/**  Human-readable explanation derived from the same attribution record. */
	explanation: string,
};

/**  One provider considered for one field, in declared precedence order. */
export type FederatedProviderDto = {
	/**  Physical source name. */
	source: string,
	/**  Attribute name as the source declares it. */
	attribute: string,
	/**  `observed`, `observed-nothing`, `did-not-see-document`, or `not-asked`. */
	verdict: string,
	/**  Observed JSON value, when present. */
	value: unknown | null,
	/**  Why the provider was not asked, when applicable. */
	reason: string | null,
	/**  Adapter-internal fallback declaration. */
	declared_fallback: string[],
};

/**  Catalog-persisted identity of the schema used for this response. */
export type FederatedSchemaDto = {
	/**  Stable schema name. */
	name: string,
	/**  Persisted catalog version. */
	version: number,
	/**  Persisted content checksum for that exact version. */
	checksum: string,
	/**  Entity names in the persisted schema. */
	entities: string[],
	/**  Arrow count. */
	arrow_count: number,
	/**  Attribute count. */
	attribute_count: number,
	/**  Equation count. */
	equation_count: number,
	/**  Whether facts in the schema require approval. */
	approval_required: boolean,
	/**  Objects currently committed to the graph. */
	object_count: number,
	/**  Review proposals currently retained. */
	proposal_count: number,
};

/**  What became of one physical source. */
export type FederatedSourceDto = {
	/**  Stable connector name. */
	source: string,
	/**  `ran` or `refused`. */
	outcome: string,
	/**  `virtual` or `materialized` when the source ran. */
	execution: string | null,
	/**  `fresh`, `cached`, or `None` when refused. */
	freshness: string | null,
	/**  Cached-answer age; zero for a fresh read. */
	age_ms: number | null,
	/**  Physical candidates examined. */
	scanned: number,
	/**  Rows surviving residual filtering. */
	returned: number,
	/**  Filters executed by the source. */
	pushed: string[],
	/**  Filters executed by CatDB after the source answered. */
	residual: string[],
	/**  Typed refusal rendered for the user when the source did not run. */
	refusal: string | null,
};

/**  Where one old field goes. */
export type FieldMoveDto = {
	/**  The source attribute. */
	from: string,
	/**  The source entity it is observed on. */
	from_entity: string,
	/**  The destination path, rendered. */
	to_path: string,
	/**  The destination path's arrows, in application order. */
	to_arrows: string[],
	/**  The destination attribute observed at the end of the path. */
	to_attr: string,
	/**  Other source attributes landing on the same slot — their values compete. */
	shared_with: string[],
	/**  The whole move on one line. */
	rendered: string,
};

/**
 *  One markdown file surfaced to the sidebar tree. Produced either from the
 *  engine's index (after an import) or, before the first import finishes, from a
 *  live filesystem scan — see [`crate::engine::list_workspace_files`].
 */
export type FileEntry = {
	/**  Absolute path to the file. */
	path: string,
	/**  File name including extension (e.g. `overview.md`). */
	name: string,
	/**  Absolute path of the containing directory. */
	dir: string,
	/**  Modification time in milliseconds since the Unix epoch. */
	mtime: number | null,
	/**
	 *  File size in bytes (an `f64` so it round-trips through JSON losslessly for
	 *  realistic document sizes).
	 */
	size: number | null,
	/**
	 *  True when a gitignore/`.contextignore` rule matched the file (the tree
	 *  dims it). Index-listed documents are never ignored (the ingest scan drops
	 *  them before they reach the index); only the fs-fallback listing sets this.
	 */
	ignored: boolean,
};

/**
 *  Payload for the `mdreader://fs-changed` event. tauri-specta emits a typed
 *  `events.fsChanged` listener into the bindings.
 */
export type FsChanged = {
	/**  Absolute path of the changed file. */
	path: string,
	/**
	 *  Coarse change kind: `"any"` for a settled change, `"continuous"` while a
	 *  path is still being written (the debouncer timed out mid-write).
	 */
	kind: string,
	/**
	 *  The workspace generation this watcher was armed under. The frontend
	 *  discards events whose generation is not the current one, so a *previous*
	 *  watcher's still-draining events can never drive the new workspace.
	 */
	generation: number,
};

/**
 *  A snapshot of index-build progress: the payload streamed on the import
 *  [`Channel`] *and* the value [`import_status`] returns. Deliberately coarse —
 *  see the module docs on progress granularity.
 */
export type ImportProgress = {
	/**
	 *  `"idle"` (no import yet), `"loading"` (constructing/downloading the
	 *  embedding model), `"importing"` (in flight), `"reembedding"` (in
	 *  flight, and re-embedding the whole workspace because the embedding
	 *  model changed), `"done"`, `"model-unavailable"` (the embedding model
	 *  could not be loaded — the workspace is open and readable, but nothing
	 *  could be indexed and the semantic arm is off), or `"error"` (the index
	 *  build itself failed).
	 */
	phase: string,
	/**
	 *  Files processed so far (equals `files_total` on `done`; the atomic import
	 *  gives no intermediate count).
	 */
	files_done: number,
	/**  Files the pre-scan found (the denominator the spinner shows). */
	files_total: number,
	/**  Chunks embedded in this pass (0 when a re-import finds nothing changed). */
	chunks_embedded: number,
	/**  The failure message when `phase == "error"`. */
	error: string | null,
};

/**
 *  One way the mapping fails to determine a source concept from its image.
 *
 *  See [`catdb_core::coverage`] for what "loss" does and does not claim: it is
 *  a statement about the mapping, never a claim that a lossless mapping is
 *  invertible.
 */
export type InformationLossDto = {
	/**
	 *  `"dropped"`, `"entities_merged"`, `"arrows_merged"`, or
	 *  `"attributes_overwritten"`.
	 */
	kind: string,
	/**  The shared destination image, rendered; empty for `"dropped"`. */
	image: string,
	/**  The source concepts involved. */
	sources: string[],
	/**  The kernel's own sentence about it — not re-worded here. */
	detail: string,
};

/**
 *  One extracted fact derived from a span of a document, with everything the
 *  Inspector renders about it.
 */
export type InspectedFact = {
	/**  The fact's id — the object id or the morphism id (uuid string). */
	fact_id: string,
	/**  `"object"` or `"morphism"`. */
	kind: string,
	/**  The overlay schema the fact is typed against. */
	schema: string,
	/**  Qualified entity (objects) or arrow (morphisms) name. */
	name: string,
	/**  The object's payload as compact JSON; `None` for a morphism. */
	value: string | null,
	/**  Source endpoint (uuid string); `None` for an object. */
	source_id: string | null,
	/**  Target endpoint (uuid string); `None` for an object. */
	target_id: string | null,
	/**  The rule that fired (e.g. `D1`), so a reviewer can see *why*. */
	rule: string,
	/**  Extractor id and version that proposed it. */
	extractor: string,
	/**  Full derivation record. */
	provenance: FactProvenanceDto,
	/**  `"proposed"`, `"approved"`, or `"rejected"`. */
	state: string,
	/**  Who set that state, when anyone has. */
	reviewer: string | null,
	/**
	 *  Whether the fact is *actually* committed to the overlay graph right
	 *  now — read from storage, not inferred from [`Self::state`].
	 */
	in_graph: boolean,
	/**
	 *  blake3 of the cited text **as it stood when the reviewer ruled on it**;
	 *  `None` while the fact is unreviewed.
	 */
	reviewed_content_hash: string | null,
	/**
	 *  The cited text has changed since the review was made.
	 *
	 *  Only ever true for a **preserved rejection**: a re-import keeps a
	 *  rejection rather than silently re-proposing the claim a human ruled
	 *  out, and raises this instead. Render it as an explicit affordance —
	 *  *"previously rejected; the source has since changed — review again?"* —
	 *  so un-rejecting stays a deliberate act. (An approval whose text changed
	 *  is reset to `proposed` outright, which clears the review, so this stays
	 *  false for it.)
	 */
	source_changed_since_review: boolean,
};

export type LibraryAvailability = { kind: "available" } | { kind: "missing" } | { kind: "unreadable" } | { kind: "not-directory" };

export type LibraryCleanupReason = "managed-state-unavailable" | "rollback-failed";

export type LibraryCleanupStatus = { kind: "complete" } | { kind: "pending"; source_count: number };

export type LibraryError = { kind: "invalid-root" } | { kind: "duplicate-root" } | { kind: "source-not-found" } | { kind: "source-unavailable" } | { kind: "active-source" } | { kind: "grant-mismatch" } | { kind: "open-failed" } | { kind: "corrupt-registry" } | { kind: "unsupported-version"; found: number; expected: number } | { kind: "persist-failed" } | { kind: "cleanup-failed"; reason: LibraryCleanupReason } | { kind: "needs-native-repick" };

export type LibraryIndexState = "present" | "not-created" | "unknown";

export type LibrarySnapshot = {
	version: number,
	sources: LibrarySourceDto[],
	cleanup: LibraryCleanupStatus,
};

export type LibrarySourceDto = {
	id: string,
	name: string,
	path: string,
	state: LibraryAvailability,
	index_state: LibraryIndexState,
	active: boolean,
	restore_candidate: boolean,
};

/**
 *  Why a workspace listing could not be produced.
 *
 *  Typed on purpose. `Unreadable` is the operating system **refusing to read**
 *  the folder — on macOS that is the privacy (TCC) layer withholding
 *  `~/Documents`, `~/Desktop` or `~/Downloads` from an app that holds no grant;
 *  elsewhere it is an ordinary mode denial. That is a categorically different
 *  fact from a folder we read perfectly well which simply holds no markdown,
 *  and the two must never render the same. Collapsing them is precisely what
 *  let a permission denial reach the user as "No markdown files in this folder
 *  yet." — an answer that is not merely unhelpful but false.
 */
export type ListingError =
/**
 *  The folder could not be READ. Carries the folder, the OS's own words,
 *  and what the user has to do about it.
 */
{ kind: "unreadable";
/**  The folder the walk was refused on. */
path: string;
/**  The underlying OS error, verbatim. */
reason: string;
/**  The concrete grant the user must make, and where. */
remedy: string } |
/**
 *  Every other listing failure (no workspace open, a superseded epoch, an
 *  index read that failed).
 */
{ kind: "failed";
/**  The failure, as text. */
message: string };

/**  A source concept and where it lands. */
export type MappedConceptDto = {
	/**  The source concept. */
	concept: ConceptDto,
	/**  Its image, rendered (`Item`, `Item.label`, `Item::item_title`). */
	image: string,
	/**
	 *  Other source concepts landing on the same image. Empty means the image
	 *  determines this one.
	 */
	shared_with: ConceptDto[],
};

/**
 *  A composed chain: either a validated composite, or exactly why not.
 *
 *  Failure is part of the value rather than an error string, because "leg 1
 *  does not validate" is something the Explorer must *draw* — on the leg — not
 *  flash as a toast.
 */
export type MappingCompositionDto = {
	/**  The legs, in order. */
	legs: CompositionLegDto[],
	/**
	 *  The schemas the chain passes through, source first. Present even when
	 *  composition failed, so the Explorer can draw the intended chain.
	 */
	chain: string[],
	/**  True when the composite is a validated first-class mapping. */
	validated: boolean,
	/**  The composite's coverage, when there is a composite. */
	coverage: MappingCoverageDto | null,
	/**  Why not, when there is not. */
	failure: CompositionFailureDto | null,
	/**
	 *  Everything true about the composite that must not be ignored: inherited
	 *  waivers, a degraded write capability.
	 */
	warnings: string[],
};

/**  What a mapping carries, what it drops, and what that costs. */
export type MappingCoverageDto = {
	/**  Source schema name. */
	src: string,
	/**  Destination schema name. */
	dst: string,
	/**  Source concepts with an image. */
	mapped: MappedConceptDto[],
	/**  Source concepts with none (a validated mapping has none). */
	unmapped: ConceptDto[],
	/**  Concepts the mapping maps that the source schema does not declare. */
	foreign: ConceptDto[],
	/**  Every determination the mapping loses. */
	loss: InformationLossDto[],
	/**  Destination concepts nothing in the source reaches. **Not loss.** */
	unreached_destination: ConceptDto[],
	/**  True when the mapping maps exactly the source's concepts. */
	total: boolean,
	/**  True when every source concept is determined by its image. */
	lossless: boolean,
};

/**  One registered mapping, as the Explorer lists it. */
export type MappingSummaryDto = {
	/**  The registered name (e.g. `F_parse`). */
	name: string,
	/**  The schema it maps from. */
	src: string,
	/**  The schema it maps to. */
	dst: string,
	/**  The persisted version ordinal; `None` before the index has been opened. */
	version: number | null,
	/**
	 *  `blake3:` checksum of the persisted mapping; `None` under the same
	 *  condition.
	 */
	checksum: string | null,
	/**  How many source entities it maps. */
	entity_count: number,
	/**  How many source arrows it maps. */
	arrow_count: number,
	/**  How many source attributes it maps. */
	attribute_count: number,
	/**  The declared write capability, as the kernel spells it. */
	write_capability: string,
	/**  Whether it maps exactly the source schema's concepts. */
	total: boolean,
	/**  Whether every source concept is determined by its image. */
	lossless: boolean,
};

/**  A place the plan cannot be applied mechanically. */
export type MigrationAmbiguityDto = {
	/**
	 *  `"entity_collision"`, `"arrow_collision"`, `"attribute_collision"`,
	 *  `"unmapped"`, or `"destination_unreached"`.
	 */
	kind: string,
	/**  The shared destination image, rendered; empty where there is none. */
	image: string,
	/**  The source concepts involved. */
	sources: string[],
	/**  Stored objects affected, for an entity collision. */
	objects: number,
	/**  A one-line rendering. */
	detail: string,
};

/**  Everything applying a mapping to this corpus would do — none of it done. */
export type MigrationPlanDto = {
	/**  The mapping's registered name. */
	mapping_name: string | null,
	/**  The source schema version. */
	src: SchemaVersionRefDto,
	/**  The destination schema version. */
	dst: SchemaVersionRefDto,
	/**  Whether the mapping validates on its own. */
	valid: boolean,
	/**  Its validation errors, when it does not. */
	validation_errors: string[],
	/**  Waivers its validation leaned on. */
	waivers: string[],
	/**  Where each source entity's rows go. */
	entity_moves: EntityMoveDto[],
	/**  Where each source arrow goes. */
	arrow_moves: ArrowMoveDto[],
	/**  Where each old field goes. */
	field_moves: FieldMoveDto[],
	/**  The mapping's coverage and loss analysis. */
	coverage: MappingCoverageDto,
	/**  Per-entity object counts over the live corpus. */
	objects: EntityObjectCountDto[],
	/**  Total objects that move without a decision. */
	auto_mapped_objects: number,
	/**  Total objects that need one. */
	objects_needing_decision: number,
	/**  Every place the plan cannot be applied mechanically. */
	ambiguities: MigrationAmbiguityDto[],
	/**  What Σ did, or why it did not run. */
	sigma: SigmaOutcomeDto,
	/**  Everything the plan is NOT claiming. Render these verbatim. */
	notes: string[],
};

export type PickedLibrarySource = {
	source: LibrarySourceDto | null,
	added: boolean,
};

/**  Reply returned by [`ping`]. */
export type PingResponse = {
	/**  The message echoed back to the caller. */
	echoed: string,
	/**  The desktop shell's crate version. */
	version: string,
};

/**
 *  One typed edge in a projection.
 *
 *  It carries no provenance and no id: the engine's morphism read
 *  (`morphisms_with_arrow_prefix`) returns `(arrow, source, target)` and
 *  nothing else. Rather than invent the missing fields, the projection says
 *  only what storage actually knows.
 */
export type ProjectedMorphism = {
	/**  Qualified arrow name (e.g. `architecture_overlay.exposes`). */
	arrow: string,
	/**  Source object id (uuid string). */
	source: string,
	/**  Target object id (uuid string). */
	target: string,
};

/**  One object in a projection of the corpus through a schema. */
export type ProjectedObject = {
	/**  Object id (uuid string). */
	id: string,
	/**  Qualified entity name (e.g. `decision_overlay.Decision`). */
	entity: string,
	/**  The object's payload, as compact JSON (specta has no `Value` type). */
	value: string,
	/**  Where the fact came from. */
	provenance: FactProvenanceDto,
};

/**  The corpus seen through one schema. */
export type Projection = {
	/**  The schema projected through. */
	schema: string,
	/**  Its objects, ordered by entity then id. */
	objects: ProjectedObject[],
	/**  Its morphisms, ordered by arrow then endpoints. */
	morphisms: ProjectedMorphism[],
	/**  True when `limit` cut the object list short. */
	truncated: boolean,
};

/**
 *  The chunk → section → document → file → source provenance ids (uuids as
 *  strings), present when `explain` was requested.
 */
export type ProvenanceDto = {
	/**  The matched chunk id. */
	chunk_id: string,
	/**  The chunk's section id. */
	section_id: string,
	/**  The section's document id. */
	document_id: string,
	/**  Source-relative stored path. */
	file_path: string,
	/**  The attributing source's id, if any. */
	source_id: string | null,
	/**  That source's root directory, if any. */
	source_root: string | null,
};

/**  What rejecting a fact wrote. */
export type RejectionOutcomeDto = {
	/**  The fact that was rejected. */
	fact_id: string,
	/**
	 *  Ids retracted from the overlay graph. Empty when the fact had never
	 *  been approved — nothing was written, so nothing is undone.
	 */
	retracted: string[],
	/**
	 *  Morphisms rejected alongside an object rejection (an edge whose
	 *  endpoint is rejected cannot stand).
	 */
	cascaded: string[],
};

/**  Per-component contributions behind a related score. */
export type RelatedComponentsDto = {
	/**  Link/span-graph walk (depth-decayed, ≤ 2 hops). */
	graph: number | null,
	/**  Shared concepts (Jaccard over the two concept sets). */
	concept: number | null,
	/**  Document-centroid vector similarity. */
	vector: number | null,
};

/**
 *  A related document on the wire: its path (relative + absolute), name, the
 *  unified score, and the per-component decomposition the rail tooltips show.
 */
export type RelatedDocDto = {
	/**  The related document's id (uuid string). */
	document_id: string,
	/**  Source-relative stored path. */
	file_path: string,
	/**  Absolute path the reader opens. */
	abs_path: string,
	/**  The document's file name (basename). */
	name: string,
	/**  Combined score (graph + concept + vector). */
	score: number | null,
	/**  Per-component contributions. */
	components: RelatedComponentsDto,
};

/**
 *  The outcome of a [`save_doc`]. A tagged struct (mirroring [`crate::engine::WikiResolution`]'s
 *  shape rather than a serde-tagged Rust enum, which specta emits less ergonomically):
 *  `status == "saved"` carries the fresh provenance the buffer re-anchors to;
 *  `status == "conflict"` carries the on-disk hash the file *actually* has, and
 *  guarantees NOTHING was written. A conflict is an expected outcome, not an
 *  error, so it rides the `Ok` channel — only hard failures (containment, IO)
 *  surface as `Err(String)`.
 */
export type SaveOutcome = {
	/**
	 *  `"saved"` (the write landed) or `"conflict"` (the on-disk hash did not
	 *  match `expected_hash`; the file was left untouched).
	 */
	status: string,
	/**
	 *  blake3 hex of the freshly-written bytes — the anchor the buffer adopts so
	 *  the watcher's echo of this very write is recognised as a self-write
	 *  (`saved` only).
	 */
	new_hash: string | null,
	/**
	 *  Modification time of the freshly-written file, ms since the Unix epoch
	 *  (`saved` only).
	 */
	mtime: number | null,
	/**
	 *  The hash the file *currently* holds on disk when `status == "conflict"` —
	 *  the anchor a subsequent forced overwrite (or a reload) re-bases onto.
	 */
	current_hash: string | null,
};

/**  One generating arrow, with its domain and codomain. */
export type SchemaArrowDto = {
	/**  Arrow name. */
	name: string,
	/**  Domain entity. */
	dom: string,
	/**  Codomain entity. */
	cod: string,
};

/**  One attribute of an entity. */
export type SchemaAttributeDto = {
	/**  Attribute name. */
	name: string,
	/**  Typeside type of its values. */
	ty: string,
	/**  Whether it may be absent on a row. */
	nullable: boolean,
};

/**  One difference between two schema versions. */
export type SchemaChangeDto = {
	/**
	 *  The change class, e.g. `"entity_added"`, `"attribute_altered"`,
	 *  `"equation_removed"`.
	 */
	class: string,
	/**
	 *  `"schema"`, `"type"`, `"entity"`, `"arrow"`, `"attribute"`, or
	 *  `"equation"`.
	 */
	kind: string,
	/**  What changed, by name (or the law's rendering, for an equation). */
	subject: string,
	/**  The before/after detail, rendered. */
	detail: string,
};

/**  A registered schema, fully introspected. */
export type SchemaDetail = {
	/**  Schema name. */
	name: string,
	/**
	 *  The engine's persisted version ordinal; `None` before the index has
	 *  been opened (see [`SchemaSummary::version`]).
	 */
	version: number | null,
	/**
	 *  `blake3:` checksum of the persisted schema; `None` under the same
	 *  condition.
	 */
	checksum: string | null,
	/**  Typeside type names the attributes draw from, sorted. */
	typeside: string[],
	/**  Entities with their attributes. */
	entities: SchemaEntityDto[],
	/**  Generating arrows with domain and codomain. */
	arrows: SchemaArrowDto[],
	/**  Path equations. */
	equations: SchemaEquationDto[],
	/**  Whether the engine requires approval for facts in this schema. */
	approval_required: boolean,
};

/**  What changed between two versions of a schema. */
export type SchemaDiffDto = {
	/**  The older side. */
	from: SchemaVersionRefDto,
	/**  The newer side. */
	to: SchemaVersionRefDto,
	/**
	 *  True exactly when nothing changed — the same answer the content
	 *  checksums give, by construction.
	 */
	identical: boolean,
	/**  Every difference. */
	changes: SchemaChangeDto[],
	/**  One entry per concept of the OLD version. Empty when `identical`. */
	classification: ConceptClassificationDto[],
	/**  Concepts only the new version declares. */
	introduced: ConceptDto[],
};

/**  One entity, with the attributes observed on it. */
export type SchemaEntityDto = {
	/**  Entity name (schema-local, as the schema declares it). */
	name: string,
	/**  Its attributes, sorted by name. */
	attributes: SchemaAttributeDto[],
};

/**  One path equation the schema imposes. */
export type SchemaEquationDto = {
	/**  The law as the kernel renders it (`Dependency.via.exposes = Dependency.provider`). */
	law: string,
	/**  Entity both sides start at. */
	start: string,
	/**  Arrows composed on the left, in application order. */
	lhs: string[],
	/**  Arrows composed on the right, in application order. */
	rhs: string[],
};

/**  One registered schema, as the **Semantic view** picker lists it. */
export type SchemaSummary = {
	/**  Schema name (e.g. `decision_overlay`). */
	name: string,
	/**
	 *  The engine's persisted version ordinal for this schema, counting from
	 *  1 in order of first appearance — `None` before the index has been
	 *  opened, when the shape is known from the registration but no version
	 *  has been assigned to it yet.
	 */
	version: number | null,
	/**
	 *  `blake3:` checksum of the persisted schema. Two versions are identical
	 *  exactly when these match. `None` under the same condition as
	 *  [`Self::version`].
	 */
	checksum: string | null,
	/**  Its entities, sorted. */
	entities: string[],
	/**  How many generating arrows it declares. */
	arrow_count: number,
	/**  How many attributes it declares. */
	attribute_count: number,
	/**  How many path equations (laws) it imposes. */
	equation_count: number,
	/**
	 *  Whether the engine requires human approval before a fact may be
	 *  asserted into this schema — true exactly for the overlays.
	 */
	approval_required: boolean,
	/**
	 *  How many objects of this schema are currently committed to the graph.
	 *  For an approval-required schema this is the count of *approved* facts,
	 *  because nothing else can be in there.
	 */
	object_count: number,
	/**
	 *  How many claims the proposal store holds for this schema, in any review
	 *  state. Always `0` for a schema that carries no reviewable assertions.
	 */
	proposal_count: number,
};

/**  Which version a diff side refers to. */
export type SchemaVersionRefDto = {
	/**  The catalog's content-derived id (uuid string), when persisted. */
	schema_id: string | null,
	/**  The schema's name. */
	name: string,
	/**  The version ordinal, when persisted. */
	version: number | null,
	/**  `blake3:` content checksum. */
	checksum: string,
};

/**  A streamed batch: the `"lexical"` first pass, then the `"final"` hybrid pass. */
export type SearchBatch = {
	/**  `"lexical"` (FTS-only first pass) or `"final"` (hybrid). */
	phase: string,
	/**  The hits for this phase, best-first. */
	hits: SearchHitDto[],
	/**
	 *  The workspace epoch generation this batch was produced under. `finish`
	 *  releases the state lock before the send below, so a switch could still
	 *  interleave one batch onto the channel — the frontend discards any batch
	 *  whose generation is not the current one (belt+suspenders over the lock).
	 */
	generation: number,
	/**
	 *  Set when the semantic arm was **wanted and could not run** — see
	 *  [`SearchResults::semantic_unavailable`]. Carried on the batch as well as
	 *  the resolved value so a consumer that renders streamed phases cannot
	 *  paint a lexical-only list as the hybrid ranking, even for an instant.
	 */
	semantic_unavailable: string | null,
};

/**
 *  One hybrid-search hit on the wire: provenance (path, heading breadcrumb,
 *  line range), per-modality ranks, boost contributions, an optional explain
 *  breakdown, plus the absolute path the reader opens and the file mtime the
 *  `Recent` intent sorts on.
 */
export type SearchHitDto = {
	/**  The matched chunk id (uuid string). */
	chunk_id: string,
	/**  The chunk's document id (uuid string). */
	document_id: string,
	/**  Source-relative stored path of the document. */
	file_path: string,
	/**  Absolute path the reader opens (source root + stored path). */
	abs_path: string,
	/**  The document's file name (basename). */
	name: string,
	/**  Heading breadcrumb of the chunk's section. */
	heading_path: string[],
	/**  First source line of the section (1-based, inclusive) — the jump target. */
	start_line: number,
	/**  Last source line of the section (1-based, inclusive). */
	end_line: number,
	/**  Final score: fused RRF plus boosts (higher is better). */
	score: number | null,
	/**  The fused RRF score before boosts. */
	rrf_score: number | null,
	/**  Recorded boost contributions. */
	boosts: BoostsDto,
	/**  1-based rank in the lexical result list, if the chunk appeared there. */
	lex_rank: number | null,
	/**  1-based rank in the semantic result list, if the chunk appeared there. */
	sem_rank: number | null,
	/**  Preview snippet (FTS-highlighted when the hit is lexical). */
	snippet: string,
	/**  Modification time of the document file, ms since the Unix epoch. */
	mtime: number | null,
	/**  The full breakdown, present when `explain` was requested. */
	explain: ExplainDto | null,
};

/**
 *  Options for [`search`], mirrored from the engine's [`SearchOptions`] with
 *  the fields the palette drives.
 */
export type SearchQuery = {
	/**  Maximum hits per phase. */
	limit: number,
	/**  Skip the vector arm entirely (the `Exact` intent) — one phase only. */
	lexical_only: boolean,
	/**  Attach the full [`HitExplain`] breakdown to every hit. */
	explain: boolean,
};

/**
 *  What a [`search`] produced, and whether it is the full ranking.
 *
 *  The hits alone cannot say this: a hybrid pass that quietly lost its vector
 *  arm returns fewer, differently-ordered hits that look exactly like a normal
 *  result set. So the outcome carries the distinction explicitly, and the caller
 *  has to look at it to get at the hits.
 */
export type SearchResults = {
	/**  The final hits, best-first. */
	hits: SearchHitDto[],
	/**
	 *  `None` when the ranking is what was asked for — either a full hybrid pass,
	 *  or a lexical-only pass the caller requested (the `Exact` intent). `Some`
	 *  carries the reason the semantic arm could not run when it *was* asked for
	 *  (typically: the embedding model could not be loaded), so `hits` is a
	 *  lexical-only list and must be presented as one.
	 */
	semantic_unavailable: string | null,
};

/**  What Σ did, or why it did not run. */
export type SigmaOutcomeDto = {
	/**  `"not_needed"`, `"not_attempted"`, `"ran"`, or `"refused"`. */
	state: string,
	/**  Why it was not attempted. */
	reason: string | null,
	/**  Σ's own refusal message. */
	error: string | null,
	/**
	 *  Which chase bound was hit (`"depth"`, `"element"`, `"round"`), when the
	 *  refusal was a bound rather than a defect in the input.
	 */
	limit: string | null,
	/**  Rows in the source instance the inspection derived. */
	rows_in: number | null,
	/**  Rows in Σ's output. */
	rows_out: number | null,
	/**  Output rows Σ invented (labelled nulls). */
	labelled_nulls: number | null,
	/**  Elements the chase created. */
	elements: number | null,
	/**  How deeply the labelled nulls nested. */
	depth: number | null,
	/**  Merges the chase performed — irreversible identifications. */
	merges: number | null,
	/**  Fixpoint rounds the chase ran. */
	rounds: number | null,
};

/**  A source span, exactly as the engine located it. */
export type SourceSpanDto = {
	/**  Repo-relative file. */
	file: string,
	/**  First line (1-based, inclusive). */
	start_line: number | null,
	/**  Last line (1-based, inclusive). */
	end_line: number | null,
	/**  blake3 of exactly those lines. */
	content_hash: string | null,
};

/**
 *  A document span to inspect. Absolute path (the shape the reader holds) plus
 *  an inclusive 1-based line range; a fact is returned when its cited span
 *  **overlaps** the range.
 */
export type SpanQuery = {
	/**  Absolute path of the document, inside the granted workspace. */
	path: string,
	/**  First line of the selection (1-based, inclusive). */
	start_line: number,
	/**  Last line of the selection (1-based, inclusive). */
	end_line: number,
};

export type UpdateInfo = {
	version: string,
	currentVersion: string,
	notes: string | null,
};

/**  An object named by a violation. */
export type ViolatingObjectDto = {
	/**  Object id (uuid string). */
	id: string,
	/**  Qualified entity name. */
	entity: string,
	/**  The markdown the object was derived from, when it carries a span. */
	source: SourceSpanDto | null,
};

/**  One violated law, field for field from the engine. */
export type ViolationDto = {
	/**  The schema whose law failed. */
	schema: string,
	/**  The law, as the kernel renders it. */
	law: string,
	/**  Arrows composed on the left. */
	lhs_path: string[],
	/**  Arrows composed on the right. */
	rhs_path: string[],
	/**  The object the two paths disagree on — located in the markdown. */
	subject: ViolatingObjectDto,
	/**
	 *  Where the left path lands; `None` when a morphism on that side is
	 *  missing, which is itself the failure.
	 */
	lhs: ViolatingObjectDto | null,
	/**  Where the right path lands; `None` as above. */
	rhs: ViolatingObjectDto | null,
};

/**
 *  Payload for the `mdreader://watch-error` event — a *runtime* watcher failure
 *  (raised from the notify callback, distinct from the command-time errors
 *  the library watch command returns). The frontend surfaces it as a degraded watcher
 *  status in the StatusBar.
 */
export type WatchError = {
	/**  Human-readable description of the watcher failure. */
	message: string,
	/**
	 *  The workspace generation this watcher was armed under (see
	 *  [`FsChanged::generation`]). An *old* watcher's error must not mark the new
	 *  watcher failed, so the frontend discards generation mismatches.
	 */
	generation: number,
};

/**  One candidate when a wikilink target is ambiguous. */
export type WikiCandidate = {
	/**  Absolute path to the candidate document. */
	path: string,
	/**  The candidate's file name. */
	name: string,
};

/**  The outcome of resolving a `[[wikilink]]` against the index. */
export type WikiResolution = {
	/**
	 *  `"resolved"` (exactly one match), `"ambiguous"` (several — see
	 *  `candidates`), or `"unresolved"` (none).
	 */
	status: string,
	/**  Absolute path of the resolved document (`resolved` only). */
	path: string | null,
	/**  File name of the resolved document (`resolved` only). */
	name: string | null,
	/**
	 *  1-based source line of the requested heading within the resolved
	 *  document, when a heading was given and matched.
	 */
	line: number | null,
	/**  The matches when `status == "ambiguous"`. */
	candidates: WikiCandidate[],
};

/**
 *  The canonical grant plus the generation the watcher was armed under, returned
 *  by the library-source watch transaction. The frontend adopts `generation` as the reference it
 *  filters `mdreader://fs-changed` / `mdreader://watch-error` events against.
 */
export type WorkspaceGrant = {
	/**  Canonical granted root. */
	root: string,
	/**  The epoch generation this grant + watcher belong to. */
	generation: number,
};

/**
 *  A file listing plus which side produced it: `true` = engine index (post
 *  import), `false` = the live filesystem fallback (before the first import
 *  finishes). The StatusBar surfaces the distinction.
 */
export type WorkspaceListing = {
	/**  The rows the sidebar tree renders. */
	entries: FileEntry[],
	/**  Whether `entries` came from the engine's index. */
	from_index: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}
